/**
 * The locale modules of ECharts that AWE registers (`echarts/i18n/langXX-obj`) are namespaces of texts without types
 */
declare module "echarts/i18n/lang*-obj" {
  export const time: unknown;
  export const legend: unknown;
  export const toolbox: unknown;
  export const series: unknown;
  export const aria: unknown;
}
